# Majority voting across all variants with adaptive score-based confidence
def run(env):
    out = {}
    n_questions = len(env.questions)
    budget_per_q = env.budget // n_questions

    for q in env.questions:
        qid = q["id"]
        answer_info = {}  # answer -> {'count': int, 'scores': [float]}

        # Collect samples cycling through variants
        for i in range(budget_per_q):
            variant = i % env.n_variants
            answer, score = env.sample(qid, variant)

            if answer not in answer_info:
                answer_info[answer] = {'count': 0, 'scores': []}

            answer_info[answer]['count'] += 1
            answer_info[answer]['scores'].append(score)

        # Score combining frequency and verifier confidence
        # Prioritize high-count answers but use score as tiebreaker
        def score_answer(a):
            count = answer_info[a]['count']
            avg_score = sum(answer_info[a]['scores']) / len(answer_info[a]['scores'])
            # Weigh count heavily (primary) and avg_score as secondary signal
            return (count, avg_score)

        best_answer = max(answer_info, key=score_answer)
        out[qid] = best_answer

    env.submit(out)

